import{_ as l,C as p,o as s,c as n,j as a,a as e,a3 as o,E as d,w as i}from"./chunks/framework.D3kUw6rp.js";const h="/assets/1.BxzF3PPk.png",b="/assets/2.DSgUM4SO.png",m="/assets/3.CL0NUjst.png",c="/assets/4.DkLV6d1W.png",T=JSON.parse('{"title":"自定义书签管理页","description":"","frontmatter":{},"headers":[],"relativePath":"article/2025/bookmark/index.md","filePath":"article/2025/bookmark/index.md"}'),k={name:"article/2025/bookmark/index.md"};function u(f,t,_,g,x,P){const r=p("center");return s(),n("div",null,[t[2]||(t[2]=a("h1",{id:"自定义书签管理页",tabindex:"-1"},[e("自定义书签管理页 "),a("a",{class:"header-anchor",href:"#自定义书签管理页","aria-label":'Permalink to "自定义书签管理页"'},"​")],-1)),t[3]||(t[3]=a("h2",{id:"视频",tabindex:"-1"},[e("视频 "),a("a",{class:"header-anchor",href:"#视频","aria-label":'Permalink to "视频"'},"​")],-1)),t[4]||(t[4]=a("iframe",{src:"//player.bilibili.com/player.html?isOutside=true&aid=114912705713066&bvid=BV1oJbSz9EbV&cid=31269848629&p=1",scrolling:"no",border:"0",frameborder:"no",framespacing:"0",allowfullscreen:"true"},null,-1)),t[5]||(t[5]=o('<h2 id="重要但不常用的书签" tabindex="-1">重要但不常用的书签 <a class="header-anchor" href="#重要但不常用的书签" aria-label="Permalink to &quot;重要但不常用的书签&quot;">​</a></h2><p>浏览器是我们程序员每天打交道最多的应用（IDE 除外），而书签便是我们在浏览器上的数字资产。</p><p>我对书签的看法是它属于重要但不常用的网站，因为常用网站我基本都是通过浏览器的历史记录加自动补全的能力去快速访问的。</p><p>比如：</p><table tabindex="0"><thead><tr><th>字母</th><th>网址</th></tr></thead><tbody><tr><td>b</td><td>哔哩哔哩</td></tr><tr><td>j</td><td>掘金</td></tr><tr><td>z</td><td>知乎</td></tr><tr><td>g</td><td>Github</td></tr><tr><td>s</td><td>少数派</td></tr><tr><td>d</td><td>数字尾巴</td></tr></tbody></table><p>以上是我每天打开最多次数的网址，它们都不是通过书签来打开，而是通过在浏览器的地址输入框按一个字母就可以从历史记录中快速匹配而打开的。</p><p>所以我认为书签的数据属于<code>重要但不常用</code>。</p><h2 id="碍眼的书签栏" tabindex="-1">碍眼的书签栏 <a class="header-anchor" href="#碍眼的书签栏" aria-label="Permalink to &quot;碍眼的书签栏&quot;">​</a></h2><p>我个人非常崇尚简洁，觉得浏览器的书签栏非常影响网页浏览。把一个我不经常用到的东西固定在那边是一种浪费空间的行为。特别是显示器的纵向空间本来就特别宝贵。（所以一般通过 <code>cmd</code>+<code>shift</code>+<code>b</code> 来临时用一下。）</p><p><img src="'+h+'" alt=""></p>',10)),d(r,null,{default:i(()=>[...t[0]||(t[0]=[e("显示书签栏",-1)])]),_:1}),t[6]||(t[6]=a("p",null,[a("img",{src:b,alt:""})],-1)),d(r,null,{default:i(()=>[...t[1]||(t[1]=[e("隐藏书签栏",-1)])]),_:1}),t[7]||(t[7]=o('<p>而且常驻书签栏也会有一点隐私的问题，我们偶尔截图网页内容给他人的时候，不经意的就将书签栏的数据给泄露了。虽然只是一些书签，但也是属于你的私人数据。</p><h2 id="树形的书签管理页面" tabindex="-1">树形的书签管理页面 <a class="header-anchor" href="#树形的书签管理页面" aria-label="Permalink to &quot;树形的书签管理页面&quot;">​</a></h2><p>我偏偏是一个数据整理的强迫症患者，经常会审视自己拥有的数字资产，比如项目代码，照片，文档，甚至歌单，也包括书签。</p><p>我感觉对数字资产做整理，归类，剔除，沉淀、这些行为特别解压。最终以一个爽快的「清空回收站」结尾。</p><p>就跟现实生活中收拾桌面，沙发，抽屉一样，把不用的丢到垃圾筒，有用的归纳摆放好，最终把垃圾袋一封扔掉。神清气爽！</p><p>所以我隔一段时间就会打开这个书签管理页面来看看，我有哪些书签，哪些是需要重新归类，哪些是已经不重要了需要删除。</p><p><img src="'+m+'" alt=""></p><p>可是这个树形的管理界面我非常不喜欢，它无法让我以一个平铺的，全局的视角去审视我的书签，需要挨个点击文件夹节点，才能显示当前文件夹的书签列表。</p><p>我很追求对数据的「掌控感」，但是这种每次只能看到局部的体验很不舒服。</p><p>自从有了 Figma 之后我就知道原来我喜欢这样的全局浏览方式，所有设计稿都在一个不断延伸的画布，可以非常方便的看完所有页面的设计稿，也更好的理解业务。</p><p>苹果最近两年推出的「无边记」也不错，也是一种画布形式的笔记，用来记录一些非线性，非流式的内容非常好。</p><p>于是我就想着开发一个符合自己预期的书签管理器，它的操作方式和 「figma」 类似，可以缩放和平移，让我以全局的视角去看我的书签。</p><h2 id="betterbookmark" tabindex="-1">BetterBookmark <a class="header-anchor" href="#betterbookmark" aria-label="Permalink to &quot;BetterBookmark&quot;">​</a></h2><ul><li><a href="https://chromewebstore.google.com/detail/better-bookmarks/ieahkhpkiipfkiecndclbbfjfhceiknh?authuser=0&amp;hl=zh-CN" target="_blank" rel="noreferrer">谷歌安装地址</a></li><li><a href="https://github.com/dogodo-cc/chrome-bookmarks" target="_blank" rel="noreferrer">仓库地址</a></li></ul><p><img src="'+c+'" alt=""></p><p>这就是我理想的书签管理页面，它平铺了所有文件夹。这些文件夹可以随意变换大小，移动位置，我可以随意的拖动画布来审视我所有的书签。它也支持简单的拖拽归类书签。</p><p>至于重命名等这些能力我就没有搬运过来了，因为原来的书签栏那边依然可以进行这些操作。而我需要的就是这个可以全局审视的书签画布。</p><p>当然是因为懒！！</p><p>如果你也是一个书签整理爱好者，同时也喜欢这样的无限画布的方式来整理书签，那么可以试试我提供的插件，只要安装并启动，再打开书签管理页面（option+cmd+b）就可以看到效果了。</p><h2 id="操作指南" tabindex="-1">操作指南 <a class="header-anchor" href="#操作指南" aria-label="Permalink to &quot;操作指南&quot;">​</a></h2><h3 id="移动画布" tabindex="-1">移动画布 <a class="header-anchor" href="#移动画布" aria-label="Permalink to &quot;移动画布&quot;">​</a></h3><p>鼠标滚动（横向和竖向）如果你用妙空鼠标或者妙控板将非常丝滑！</p><p>Windows 用户可以通过按住鼠标中间来移动画布</p><h3 id="选择卡片" tabindex="-1">选择卡片 <a class="header-anchor" href="#选择卡片" aria-label="Permalink to &quot;选择卡片&quot;">​</a></h3><p>如果单击某个卡片，可以进行宽高的设置</p><p>按住鼠标左键可以进行框选操作，被框选到的卡片可以同时进行移动</p><h3 id="拖拽分类" tabindex="-1">拖拽分类 <a class="header-anchor" href="#拖拽分类" aria-label="Permalink to &quot;拖拽分类&quot;">​</a></h3><p>支持将卡片里的书签拖到其他卡片，直接鼠标按住拖动即可。</p>',28))])}const S=l(k,[["render",u]]);export{T as __pageData,S as default};
